			templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 2, "։ Առանց TPM-ի Windows PC-ն չի կարող մուտք գործել tafs։ KIFF-ը պահում է բանալու հանրային կեսը, սարքի անունն ու հարթակը, և երբ է ավելացվել ու վերջին անգամ օգտագործվել, որպեսզի կարողանա ստուգել ձեր պատասխանները կասեցված զանգերին և ձեր կապերի հաստատումները։</li><li><strong>Ձեր ժամացույցը՝</strong> ժամացույցը գաղտնաբառ կամ բանալի չի պահում, խոսում է միայն ձեր զուգակցված հեռախոսի հետ և երբեք չի հաստատում։ Այն, ինչ ասում եք, ուղարկում է Coach-ին կամ ձեր ընտրած taf-ին միայն որպես տեքստ, հեռախոսի միջոցով, երբ AI-ին թույլատրել եք։ Ժամացույցի սեփական խոսքի ծառայությունը՝ Apple-ինը կամ Google-ինը, ձեր խոսքերը վերածում է այդ տեքստի։ Wear OS-ում, եթե այն կանգ է առնում նախքան ավարտելը, դա անում է ձեր հեռախոսի սեփական ճանաչիչը՝ հեռախոսի վրա։ Կարող է մերժել, կանգնեցնել կամ ուղարկել Coach-ին կամ taf-ին միայն երբ ունի էկրանի կողպում կամ կոդ և ապակողպված է։ Այն, ինչ taf-ին եք ուղարկում, գնում է այդ taf-ի սեփական զրույց, կարծես հեռախոսի վրա գրած լինեիք։ Taf-ի զրույցը, ներառյալ գումարները, ամեն անգամ բացվելիս կարդացվում է հեռախոսի միջոցով, իսկ ժամացույցը պահում է միայն վերջին հաղորդագրությունները, որոնք նկարագրված են ներքևում՝ իր բաժնում։ Երբ հավելվածները փակ են, ձեր հեռախոսը նոր պատասխաններն ու հաղորդագրությունները ժամացույցին է փոխանցում համակարգի սեփական հեռախոս-ժամացույց կապով (Apple Watch-ում՝ Apple-ի, Wear OS-ում՝ Google Play ծառայությունների), որը դրանք պահում է հեռախոսում և ժամացույցում միայն մինչև ժամացույցը դրանք ընդունի. ձեր հեռախոսն արթնացնող ծանուցումը բառեր չի պարունակում։ Պատասխանը, որ գալիս է, երբ ժամացույցին չեք նայում, ցուցադրվում է նաև որպես ծանուցում՝ ձեր iPhone-ում և Apple Watch-ում կամ ձեր Wear OS ժամացույցում, իր բառերով, բայց երբեք գումարով, և մնում է, մինչև այն փակեք. կողպված Wear OS ժամացույցը ցույց է տալիս միայն, որ պատասխանը պատրաստ է։</li><li><strong>Apple Watch՝</strong> ցույց է տալիս ձեր taf-երն ու դրանց էջերը՝ առանց պահելու։ Պահում է ձեր Մուտքերը, ֆայլում, որը չի կարող կարդալ, երբ կողպված է. յուրաքանչյուր կասեցված զանգ՝ որպես իր taf-ի անուն և ինչ է խնդրում, երբեք գումար, և Coach-ի պատասխանները այն բանին, ինչ ուղարկել եք ժամացույցից, որպես տեքստ։ Եթե ժամացույցի վրա դուրս եք գալիս, պահում է նաև այն, որ դուրս եկել եք, մինչև ժամացույցի վրա նորից մուտք գործեք։ Դրանից բացի ոչինչ չի պահում, եթե ժամացույցը կոդ չունի։ Մուտքերը հեռանում են, երբ ժամացույցի վրա դուրս եք գալիս կամ ձեր iPhone-ը դուրս է գալիս, կամ հաջորդ անգամ, երբ հավելվածը բացվում կամ փակվում է առանց կոդի։ Ձայնագրություն չի անում, և միակ ծանուցումները, որ ցույց է տալիս, ձեր iPhone-ինն են։ Որպեսզի զրույցն անմիջապես բացվի, այն պահում է նաև դրանում բացված մինչև 20 զրույցներից յուրաքանչյուրի վերջին 30 հաղորդագրությունները՝ Coach-ի և ձեր tafs-ի, միայն տեքստով և երբեք գումար, Մուտքերի պես կողպված, և դրանք ջնջվում են Մուտքերի հետ, ինչպես նաև երբ զրույցը 30 օր չի բացվել։ Եթե Coach-ին ուղղված հաղորդագրությունը պահում եք ավելի ուշ ուղարկելու համար, այն պահում է նաև այդ մեկ հաղորդագրությունը՝ որպես տեքստ, առանձին ֆայլում, որը կողպված է Մուտքայինի պես, և ուղարկում է այն, երբ ձեր iPhone-ը վերադառնա։ Այն ջնջվում է ուղարկվելուց հետո, երբ ջնջում եք այն, երբ դուք կամ ձեր iPhone-ը դուրս եք գալիս, կամ եթե ժամացույցն այլևս գաղտնաբառ չունի։</li><li><strong>Wear OS՝</strong> ցույց է տալիս ձեր հաշվի էլ. փոստն ու այսօրվա օրացույցը՝ առանց պահելու։ Որպեսզի անմիջապես բացվի, պահում է, գաղտնագրված, ձեզ սպասողի քանակը և յուրաքանչյուր taf-ի անունը և արդյոք այն կանգնեցված է, թե դադարեցված. երբեք գումար, կասեցված զանգի մանրամասներ կամ taf-ի զրույց։ Սա մաքրվում է, երբ դուրս եք գալիս, երբ ժամացույցը կողպվում է կամ հանվում է դաստակից, և 24 ժամ հետո։ Պահում է ձեր Մուտքերը, որտեղ յուրաքանչյուր տող taf-ի անուն է և այն, ինչ ասում է, երբեք գումար, և մեկ հաղորդագրություն՝ հետագայի համար, որպես տեքստ։ Դուրս գալը, ժամացույցի կամ հեռախոսի վրա, մաքրում է ամենը։ Իր սալիկի համար պահում է նաև ձեզ սպասողի քանակը, ցույց տրված միայն երբ ժամացույցը ապակողպված է, և մաքրվում է, երբ դուրս եք գալիս, կամ հաջորդ անգամ, երբ սալիկը երևում է, երբ ժամացույցը կողպված է կամ չունի էկրանի կողպում։ Ժամացույցի վրա դուրս գալուց հետո պահում է նշում, որ դուրս եկել եք, մինչև նորից մուտք գործեք։ Մուտքերը հեռանում են նաև հաջորդ անգամ, երբ հավելվածը բացվում կամ փակվում է, երբ ժամացույցը կողպված է կամ չունի էկրանի կողպում։ Հետագայի համար պահված հաղորդագրությունը մնում է, մինչև ուղարկեք կամ ջնջեք, քանի որ ինքներդ եք խնդրել ուղարկել։ Եթե ժամացույցի խոսքի ծառայությունը կանգ է առնում նախքան ավարտելը, ժամացույցը ձայնագրությունն ուղարկում է ձեր հեռախոսին, որը այն վերածում է տեքստի հենց հեռախոսի վրա, երբեք սերվերում։ Ձայնագրությունը ջնջվում է երկու կողմում, երբ տեքստը վերադառնում է կամ չեղարկում եք, և առավելագույնը 2 րոպե հետո։ Միայն տեքստն է շարունակում ճանապարհը Coach-ին կամ ձեր taf-ին։ Taf-ի արդյունքը կարող է մնալ ժամացույցի ծանուցումներում, մինչև չմերժեք կամ ժամացույցի վրա դուրս չգաք։ Որպեսզի զրույցն անմիջապես բացվի, այն պահում է նաև դրանում բացված մինչև 20 զրույցներից յուրաքանչյուրի վերջին 30 հաղորդագրությունները՝ Coach-ի և ձեր tafs-ի, միայն տեքստով և երբեք գումար, գաղտնագրված, և դրանք ջնջվում են, երբ դուրս եք գալիս ժամացույցում կամ հեռախոսում, և երբ զրույցը 30 օր չի բացվել, իսկ առանց էկրանի կողպման ժամացույցը դրանցից ոչ մեկը չի պահում։ Ավելի ուշ ուղարկելու համար պահված հաղորդագրությունը ջնջվում է նաև, եթե ժամացույցն այլևս էկրանի կողպում չունի։</li><li><strong>Passkey-եր՝</strong> երբ համակարգչի վրա հաստատում եք passkey-ով, օրինակ Windows Hello կամ անվտանգության բանալի, ձեր դեմքը, մատնահետքը կամ PIN-ը մնում է համակարգչի սեփական համակարգում։ KIFF-ը պահում է passkey-ի հանրային բանալին, դրա id-ն, հաշվիչն ու անունը, երբեք որևէ գաղտնիք, և մերժում է passkey, որը համաժամացվում է այլ սարքերի հետ։</li><li><strong>Ծանուցումներ՝</strong> հեռախոսի, պլանշետի կամ iPad հավելվածը գործարկող Mac-ի վրա, երբ դրանք միացնում եք, պահում ենք սարքի push token-ը ձեր KIFF անձի id-ի հետ և այն լեզուն, որը հավելվածը ցույց է տվել։ Ծանուցումն անցնում է Apple-ի կամ Google-ի միջով միայն այն տվյալով, թե որ taf-ն ու ինչ է ուզում, իսկ դռան ծանուցման մեջ՝ գրողի անունով կամ էլ. փոստի հասցեով. երբեք գումարով կամ հարցման մանրամասներով։ Հավելվածը դրանք ավելացնում է հենց սարքի վրա, KIFF-ից, ուստի ապակողպված հեռախոսի ծանուցումը կարող է ցույց տալ գումար, վաճառող կամ անձ։ Կողպված Android հեռախոսի վրա ցույց է տալիս միայն «Taf-ին ձեզ պետք է», իսկ կողպված iPhone-ի վրա՝ նույնպես, եթե նախադիտումները միշտ ցուցադրվելու չեք սահմանել։ Windows PC-ում, Linux համակարգչում կամ macOS 12 հավելվածով Mac-ում ծանուցումները ստեղծում է հենց հավելվածը՝ աշխատելիս, առանց push token-ի և առանց որևէ այլ ընկերության։ Windows-ում և Linux-ում ցույց են տալիս, թե որ taf-ը, ինչ է ուզում անել, գումարը, ինչու և մինչև երբ. macOS 12 հավելվածում ցույց են տալիս KIFF-ի խոսքերը զանգի համար, երբ դրանք միացնում եք, և կողպված էկրանը ցույց է տալիս այն, ինչ թույլ է տալիս Mac-ի նախադիտման կարգավորումը։ Windows-ում անջատված են, մինչև միացնեք, և ցույց են տալիս միայն «Taf-ին ձեզ պետք է», երբ էկրանը կողպված է։ Էկրանի կողպումից առաջ ցուցադրված ծանուցումն իր մանրամասները պահում է Windows-ի ծանուցումների ցանկում։ Linux-ում միացված են, մինչև անջատեք, և այն, ինչ ցույց է տալիս կողպված էկրանը, կախված է ձեր աշխատասեղանից։</li><li><strong>Լեզու՝</strong> tafs ծառայությունը պահում է հաշվի լեզուն՝ նրա, ով վերջին անգամ զրուցել է Coach-ի հետ, մինչև երեք ամիս, որպեսզի taf-ի հաշվետվությունները նրանով գան։ Եթե բողոքեք որևէ պատասխանի մասին, KIFF-ը պահում է այդ պատասխանը, ձեր պատճառը և նշումը 180 օր, նույնիսկ եթե ջնջեք զրույցը. հաշիվը ջնջելը դրանք ավելի շուտ է ջնջում։ KIFF-ը դրանք նաև էլ. փոստով ուղարկում է բողոքները կարդացող թիմին, որտեղ այդ նամակը պահվում է KIFF-ի աջակցության նամակների պես։</li><li><strong>Ձեր գործիքները՝</strong> երբ գործիք եք կապում, մուտք եք գործում գործիքի սեփական մատակարարի մոտ։ Հավելվածի համար, որի մեջ planque-ը ինքն է մուտք գործում, օրինակ Stripe, կամ բանալու համար, որը տալիս եք, planque-ը այդ token-ը կամ բանալին պահում է ձեր ընկերության համար՝ գաղտնագրված։ Կառավարվող կապի համար՝ Composio-ն՝ կապի ծառայությունը, որի հետ աշխատում է planque-ը, պահում է մուտքը, և planque-ը պահում է միայն կապի գրառումը և ձեր հաստատած գործիքները (տե՛ս <a href=\"#google\">Google-ի օգտատիրոջ տվյալները</a>)։ Կապի գրառումը կարող է ներառել հաշիվը, որում մուտք է գործվել (դրա անունը կամ էլ. փոստը), որպեսզի հավելվածը ձեզ ցույց տա, թե որն է։ KIFF-ը կառավարվող կապեր օգտագործում է միայն <a href=\"/subprocessors#composio\">/subprocessors</a> (անգլերեն) հասցեում նշված հավելվածների համար։</li><li><strong>Ձեր դիտարկիչը (Chrome)՝</strong> երբ tafs ընդլայնումը զուգակցում եք հեռախոսի հետ, taf-ը կարող է աշխատել ձեր զուգակցած Chrome պրոֆիլում, միայն այն կայքերում, որոնք նշված են նրա կապում։ Այն իր սեփական ներդիրները բացում է ներդիրների խմբում, որը կարող եք տեսնել, դադարեցնել կամ կանգնեցնել, և դադարում է, երբ դրանցից որևէ մեկին դիպչում եք։ Այդ էջերը կարդում է որպես տեքստ և ձևաթղթի դաշտեր, գաղտնաբառի, քարտի և կոդի դաշտերը հանված, երբեք ձեր մյուս ներդիրները կամ այլ կայքերը։ Այդ տեքստը գործարկման մաս է կազմում և գնում է մեր արհեստական բանականության մատակարարին, և պահվում է գործարկման հետ՝ ինչպես ցանկացած գործիքի արդյունք։ Յուրաքանչյուր քայլ մտնում է Գրանցամատյան՝ կայքով և դաշտի անունով, երբեք այն, ինչ մուտքագրվել է գաղտնի դաշտում։ taf-ի կատարած յուրաքանչյուր փոփոխության համար KIFF-ը պահում է էջը առաջ և հետո, որպես տեքստ այդ դաշտերը հանված, առավելագույնը 30 օր, և ավելի շուտ ջնջում է, երբ անջատվում եք կամ ջնջում հաշիվը։ Այս էջերը կարող են ցույց տալ ուրիշ մարդկանց տվյալներ, օրինակ ձեր հաճախորդների. KIFF-ը դրանք մշակում է ձեզ համար՝ որպես մշակող։ Ընդլայնումը ձեր համակարգչում պահում է միայն իր բանալին, երբեք ձեր գաղտնաբառերը. մուտքի էջում taf-ը կանգ է առնում և խնդրում է, որ ինքներդ մուտք գործեք՝ ձեր սեփական ներդիրում։ Coach-ի հետ կարող եք զրուցել նաև ընդլայնման կողմնային վահանակից։ Coach-ը կարդում է էջը միայն այն բանից հետո, երբ թույլ եք տալիս ընդլայնման մեջ, առանձին համաձայնությամբ, որը կարող եք այնտեղ հետ վերցնել, և միշտ կարող եք հաղորդագրություն ուղարկել առանց էջի։ Երբ այնտեղից նրան հաղորդագրություն եք ուղարկում, առջևի էջը գնում է այդ հաղորդագրության հետ՝ միայն իր տեսանելի տեքստով, երբեք ոչ այն, ինչ մուտքագրել եք, բացի բանկի, վճարման, փոստի կամ առողջության կայքից կամ Coach-ի համար ձեր անջատած կայքից։ Դաշտերի արժեքները և գաղտնաբառերը չեն կարդացվում, քարտերի համարները կրճատվում են մինչև վերջին չորս թվանշանը, իսկ բանալիներն ու պիտակված գաղտնիքները քողարկվում են։ Քողարկվում են նաև էջի տեքստում անգլերեն, ֆրանսերեն, իսպաներեն կամ գերմաներեն այդպես անվանված մեկանգամյա կոդերը։ Այն գնում է մեր AI մատակարարին միայն այդ հաղորդագրության համար. tafs-ը էջը պահում է միայն մինչև պատասխանը պատրաստ լինի, իսկ կայքի անունը պահում է ձեր զրույցի հետ՝ «Կարդում է՝» ձևով, 30 օր։ Coach-ի պատասխանը կարող է մեջբերել էջը և պահվում է ձեր զրույցի հետ, ինչպես ցանկացած պատասխան։ Կողային վահանակը ցույց է տալիս այն զրույցները, որոնք սկսվել են այդ Chrome-ում՝ զուգակցելուց հետո, իսկ ձեր մյուս զրույցները մնում են ձեր հեռախոսում և մյուս սարքերում։ Երբ taf-ը աշխատում է այդ Chrome-ում ձեր մեկ այլ սարքից ուղարկված հաղորդագրության համար, վահանակը ցույց է տալիս նաև այդ գործարկումը՝ հաղորդագրությունը, դրա քայլերը և պատասխանը, բայց երբեք այդ զրույցի մնացած մասը, մինչև ջնջեք այդ զրույցը, չեղարկեք Chrome-ի զուգակցումը կամ taf-ը տեղափոխեք մեկ այլ Chrome։ Այնտեղ կարող եք նաև ֆայլեր կցել հաղորդագրությանը. ինչպես tafs հավելվածներում կցված ֆայլերը, դրանք այդ հաղորդագրության հետ գնում են մեր AI մատակարարին և պահվում են դրա հետ 30 օր կամ ավելի քիչ, եթե զրույցը հեռացվի (ֆայլը, որը ոչ մի հաղորդագրություն չի օգտագործում, մոտ մեկ ժամ), և ֆայլը կարող է բացել միայն այն կցողը։ Անջատումը կամ ապատեղադրումը ջնջում է այն, ինչ պահում է ընդլայնումը։ taf-ը երբեք չի վճարում առանց ձեր հաստատման հեռախոսում։ Յուրաքանչյուր գործող քայլի (սեղմում, մուտքագրում, ուղարկում), ներառյալ ձեր հաստատածի համար, այն պահում է նաև էջի մեկ էկրանի նկար՝ արված գործողությունից անմիջապես առաջ, գրանցամատյանի համար. երբեք միայն կարդացվող էջի համար, երբեք բանկի, դրամապանակի, գաղտնաբառերի կառավարիչի, վճարումների, առողջության կամ պետական կայքում, իսկ գաղտնաբառի, քարտի և կոդի դաշտերը թաքցվում են նկարելուց առաջ։ Քարտի համարի կամ բանալու նման տեքստը նույնպես սևացվում է, բայց այլ կերպ գրվածը դեռ կարող է երևալ։ Էկրանի նկարները պահվում են գաղտնագրված պահոցում, այդ քայլին կապված, 30 օր, հետո ինքնաշխատ ջնջվում են, կամ ավելի շուտ, երբ անջատում եք կապը, չեղարկում եք այս Chrome-ի զուգակցումը կամ ջնջում եք ձեր հաշիվը, և երբեք չեն գնում մեր արհեստական ինտելեկտի մատակարարին։ Դուք տեսնում եք յուրաքանչյուրը իր քայլի տակ՝ taf-ի Գործունեության մեջ։</li><li><strong>Ձեր taf-երի աշխատանքը՝</strong> յուրաքանչյուր taf-ի գործարկումները, զրույցները, հաշվետվությունները, հիշողության նշումները և ֆայլերը, որոնք հանձնում է, պահվում են որպես մշակող։ Ձեր հաշվի բոլորը կարող են տեսնել ձեր taf-երի հանձնած ֆայլերը։</li><li><strong>Դռներ՝</strong> երբ դուռ եք բացում, որպեսզի մարդիկ կարողանան taf-ին գրել էլ. փոստով, Slack-ով կամ Telegram-ով, tafs ծառայությունը պահում է ձեր զուգակցած յուրաքանչյուր ուղարկողին՝ նրա էլ. հասցեով, Slack-ի անդամի ID-ով կամ Telegram-ի օգտատիրոջ ID-ով (WhatsApp-ի դռան համար՝ հեռախոսահամարով), ձեր տված անունով, մինչև որ հեռացնեք դուռը կամ taf-ը։ Այն մարդու հաղորդագրությունը, ում չեք զուգակցել, սպասում է ձեզ որպես թակոց՝ ով է գրել և ինչ է ասում, վերջինից հետո մինչև 30 օր։ Զուգակցված ուղարկողի հաղորդագրությունը մտնում է taf-ի զրույցի մեջ և պահվում է զրույցի մնացած մասի պես։ Slack-ը և Telegram-ը փոխանցում են հաղորդագրությունները իրենց սեփական պայմաններով։</li><li><strong>Գնումներ՝</strong> Solo-ն և կրեդիտների փաթեթները վաճառում է Apple-ը App Store-ի միջոցով կամ Google-ը Google Play-ի վճարման միջոցով։ Նրանք մեզ հայտնում են, թե ինչ է գնվել, որ KIFF հաշվի համար (պատահական id), երբ, և իրենց գործարքի կամ պատվերի հղումները։ Նրանք մեզ չեն տալիս ձեր Apple ID-ն կամ Google հաշիվը, անունը, էլ. փոստի հասցեն կամ քարտը։</li></ul><p>Հավելվածը չունի վերլուծական կամ գովազդային հետագծիչներ։</p></section><section id=\"ai\"><h2>5. AI-ն tafs-ում</h2><p>tafs-ը օգտագործում է Anthropic-ի Claude AI-ն Coach-ի և ձեր taf-երի համար։ Այն մեզ համար գործարկում է Anthropic-ը կամ մեր ենթամշակողների էջում նշված ամպային մատակարարներից մեկը։ Այդ էջում նշված է՝ որը և որտեղ։ Հավելվածը ձեզ հարցնում է, նախքան որևէ բան դրան ուղարկելը։</p><ul><li>Ինչ է ուղարկվում՝ այն, ինչ գրում եք Coach-ին և ձեր taf-երին, ֆայլերը, որոնք կցում եք, այն, ինչ ձեր միացված հավելվածները վերադարձնում են taf-ին, երբ աշխատում է, և այն, ինչ ձեր էկրանին է, մինչ Coach-ը օգնում է ձեզ հավելվածում։</li><li>Chrome-ից՝ առջևի էջը, երբ գրում եք Coach-ին ընդլայնման կողմնային վահանակում, երբ այնտեղ թույլ եք տվել Coach-ին կարդալ էջեր։</li><li>Ինչ երբեք չի ուղարկվում՝ գաղտնաբառերն ու բանալիները, որոնք օգտագործում են ձեր միացված հավելվածները, կամ ձեր մատնահետքը։</li><li>Այն գործարկող ընկերությունն այն օգտագործում է պատասխանելու համար և ջնջում է 30 օրվա ընթացքում, եթե այն նշված չէ որպես իր օգտագործման կանոնների խախտում, կամ օրենքը չի պահանջում այն պահել։</li><li>Ոչինչ չի ուղարկվում, մինչև չթույլատրեք։ Կարող եք հետ վերցնել Հաշվում։</li></ul><p>Երբ հետ եք վերցնում, Coach-ը և ձեր taf-երը դադարում են ձեզ պատասխանել, և taf-ը, որի գործարկումները հիմնված են ձեր համաձայնության վրա, դադարեցվում է։ tafs-ը պահում է ձեր տված կամ հետ վերցրած յուրաքանչյուր համաձայնության գրառումը՝ երբ և դրա տեքստի որ տարբերակով, վերջին փոփոխությունից 10 տարի, որպեսզի ցույց տա, թե ինչի եք համաձայնել, իսկ ձեր հաշիվը ջնջելը այն ավելի շուտ է ջնջում։ <a href=\"/hy/privacy#ai-in-tafs\">KIFF-ի Գաղտնիության քաղաքականությունը</a> ունի մանրամասները։</p></section>")
